#!/usr/bin/env bash
# Generated by `node scripts/npm-trust.ts` — do not edit. Run it ONCE, by hand, after the first publish (npm needs the packages
# to exist): every package trusts the release workflow for STAGED publishing only — a staged version goes live when a
# maintainer approves it with 2FA on npmjs.com (E152). Needs npm >= 11.15 and an `npm login` with 2FA. The first call asks
# for the one-time password; tick "skip two-factor authentication for the next 5 minutes" there, and the rest runs through.
set -euo pipefail

packages=(
  @marmeon/auth
  @marmeon/cache
  marmeon
  @marmeon/core
  create-marmeon
  @marmeon/database
  @marmeon/devtools
  @marmeon/encryption
  @marmeon/http
  @marmeon/i18n
  @marmeon/live
  @marmeon/log
  @marmeon/mail
  @marmeon/notifications
  @marmeon/otel
  @marmeon/queue
  @marmeon/react
  @marmeon/redis
  @marmeon/router
  @marmeon/scheduler
  @marmeon/server
  @marmeon/session
  @marmeon/storage
  @marmeon/table
  @marmeon/testing
  @marmeon/vite
)

for package in "${packages[@]}"; do
  npm trust github "$package" --repository marmeon/marmeon --file release.yml --allow-stage-publish --yes
  sleep 2 # npm asks for a pause between calls (rate limit)
done

echo "Trusted release.yml of marmeon/marmeon (staged publishing) for ${#packages[@]} packages. Check one: npm trust list @marmeon/auth"
